<div class="section-heading"><div><div class="eyebrow">Gestão financeira</div><h1>Financeiro da plataforma</h1><p class="text-secondary mb-0">Receitas das assinaturas, módulos adicionais, despesas da operação e projeções recorrentes.</p></div></div>
<div class="row g-3 mb-4"><?php foreach([
['Receita recorrente mensal (MRR)',$metrics['mrr'],'Receita mensal equivalente das assinaturas ativas'],['Projeção anual (ARR)',$metrics['arr'],'MRR × 12'],['Recebido no mês',$metrics['received_month'],'Pagamentos de produção + receitas manuais'],['Despesas no mês',$metrics['expenses_month'],'Despesas manuais pagas'],['Resultado do mês',$metrics['net_month'],'Receitas menos despesas'],['A receber',$metrics['receivable'],'Faturas pendentes ou vencidas'],['A pagar',$metrics['payable'],'Despesas pendentes'],['Previsão próximos 30 dias',$metrics['forecast_30d'],'Cobranças previstas pelas assinaturas atuais']
] as $card):?><div class="col-md-6 col-xl-3"><div class="card metric-card h-100"><div class="card-body"><div class="metric-label"><?=htmlspecialchars($card[0])?></div><div class="metric-value">R$ <?=number_format((float)$card[1],2,',','.')?></div><small><?=htmlspecialchars($card[2])?></small></div></div></div><?php endforeach;?></div>
<div class="row g-4 mb-4"><div class="col-lg-8"><div class="card h-100"><div class="card-header"><strong>Novo lançamento da plataforma</strong></div><div class="card-body"><form method="post" action="/master/financeiro/lancamentos" class="row g-3"><?=\App\Core\CSRF::field()?><div class="col-md-2"><label class="form-label">Tipo</label><select class="form-select" name="type"><option value="expense">Despesa</option><option value="income">Receita manual</option></select></div><div class="col-md-4"><label class="form-label">Descrição</label><input class="form-control" name="description" required></div><div class="col-md-2"><label class="form-label">Valor</label><input class="form-control" type="number" step=".01" min=".01" name="amount" required></div><div class="col-md-2"><label class="form-label">Vencimento</label><input class="form-control" type="date" name="due_at"></div><div class="col-md-2"><label class="form-label">Status</label><select class="form-select" name="status"><option value="pending">Pendente</option><option value="paid">Pago</option></select></div><div class="col-md-5"><label class="form-label">Categoria</label><select class="form-select" name="category_id"><option value="">Sem categoria</option><?php foreach($categories as $c):?><option value="<?=(int)$c['id']?>"><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-7"><label class="form-label">Observação</label><input class="form-control" name="notes"></div><div class="col-12"><button class="btn btn-primary">Registrar lançamento</button></div></form></div></div></div><div class="col-lg-4"><div class="card h-100"><div class="card-header"><strong>Nova categoria</strong></div><div class="card-body"><form method="post" action="/master/financeiro/categorias"><?=\App\Core\CSRF::field()?><label class="form-label">Nome</label><input class="form-control mb-3" name="name" required><label class="form-label">Aplicação</label><select class="form-select mb-3" name="type"><option value="both">Receitas e despesas</option><option value="income">Somente receitas</option><option value="expense">Somente despesas</option></select><button class="btn btn-outline-primary">Adicionar categoria</button></form></div></div></div></div>
<div class="card mb-4"><div class="card-header"><strong>Lançamentos internos</strong></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Data</th><th>Tipo</th><th>Descrição</th><th>Categoria</th><th>Valor</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($transactions as $t):?><tr><td><?=date('d/m/Y',strtotime($t['created_at']))?></td><td><?=$t['type']==='income'?'Receita':'Despesa'?></td><td><?=htmlspecialchars($t['description'])?></td><td><?=htmlspecialchars($t['category_name']??'—')?></td><td>R$ <?=number_format((float)$t['amount'],2,',','.')?></td><td><?=htmlspecialchars(['pending'=>'Pendente','paid'=>'Pago','cancelled'=>'Cancelado'][$t['status']]??$t['status'])?></td><td><?php if($t['status']==='pending'):?><form class="d-inline" method="post" action="/master/financeiro/lancamentos/<?=(int)$t['id']?>/pagar"><?=\App\Core\CSRF::field()?><button class="btn btn-sm btn-success">Marcar pago</button></form><?php endif;?><?php if($t['status']!=='cancelled'):?><form class="d-inline" method="post" action="/master/financeiro/lancamentos/<?=(int)$t['id']?>/cancelar"><?=\App\Core\CSRF::field()?><button class="btn btn-sm btn-outline-danger">Cancelar</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$transactions):?><tr><td colspan="7"><div class="empty-state">Nenhum lançamento interno.</div></td></tr><?php endif;?></tbody></table></div></div>
<div class="card"><div class="card-header"><strong>Recebimentos das assinaturas e módulos</strong></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Data</th><th>Cliente</th><th>Origem</th><th>Valor</th><th>Status</th><th>Ambiente</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=htmlspecialchars($p['paid_at']??$p['created_at'])?></td><td><?=htmlspecialchars($p['tenant_name'])?></td><td><?=$p['purpose']==='module_addon'?'Módulo: '.htmlspecialchars($p['module_name']??'Adicional'):'Plano: '.htmlspecialchars($p['plan_name']??'Assinatura')?></td><td>R$ <?=number_format((float)$p['amount'],2,',','.')?></td><td><?=htmlspecialchars(['pending'=>'Pendente','paid'=>'Pago','failed'=>'Não aprovado','refunded'=>'Reembolsado','cancelled'=>'Cancelado'][$p['status']]??$p['status'])?></td><td><?=htmlspecialchars($p['environment']==='production'?'Produção':($p['environment']==='sandbox'?'Teste':'Legado'))?></td></tr><?php endforeach;?></tbody></table></div></div>
